def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_slack = 0.05
    return np.where(remaining >= 0, 1.0 - np.tanh(np.abs(remaining - optimal_slack) * 5.0), -2.0 * np.abs(remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_slack = 0.1
    return np.where(remaining >= 0, np.exp(-((remaining - optimal_slack) ** 2) / 0.2), -np.abs(remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, 1.0 / (remaining + 1e-7), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, np.tanh(remaining), -np.maximum(0.0, -remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -1e9 + remaining)
